using Sirenix.OdinInspector;
using UnityEngine;

/// <summary>
/// Visual model of a gun (mob or player). Pure view data, no gameplay logic.
/// Convention: the root is the right-hand grip point, the barrel points along +Z, +Y is up,
/// the shooter's left is -X. Prefabs are generated by Tools ▸ Crowds ▸ Build Weapon Models
/// (WeaponModelBuilder) from primitives; see Docs/WeaponModels.md.
/// </summary>
public class WeaponModel : MonoBehaviour
{
	[BoxGroup("Points"), Tooltip("Where the right hand holds the weapon (the weapon root is usually placed here).")]
	[SerializeField] private Transform _grip;

	[BoxGroup("Points"), Required, Tooltip("Tip of the barrel: bullet spawn point and muzzle-flash anchor. +Z = shot direction.")]
	[SerializeField] private Transform _muzzle;

	[BoxGroup("Points"), Tooltip("Left-hand target on the forend/handguard (where the LEFT WRIST bone should be). " +
	                             "Used by WeaponHandIK. Empty = one-handed weapon, no IK.")]
	[SerializeField] private Transform _leftHandTarget;

	[BoxGroup("Parts"), Tooltip("Externally visible magazine(s): hidden while reloading (player). Empty = nothing to hide.")]
	[SerializeField] private GameObject[] _magazines;

	[BoxGroup("Effects"), Tooltip("EffectsHolder id spawned at the muzzle on every shot. Empty = no flash.")]
	[SerializeField] private string _muzzleEffectId = "muzzle_flash";

	private bool _magazineVisible = true;

	public Transform Grip => _grip;
	public Transform Muzzle => _muzzle;
	public Transform LeftHandTarget => _leftHandTarget;
	public string MuzzleEffectId => _muzzleEffectId;

	/// <summary>Shows/hides the external magazine (e.g. while reloading). Cheap to call every frame.</summary>
	public void SetMagazineVisible(bool visible)
	{
		if (_magazineVisible == visible || _magazines == null)
			return;
		_magazineVisible = visible;
		foreach (var magazine in _magazines)
			if (magazine != null)
				magazine.SetActive(visible);
	}
}
